class Model:
    def __init__(self):
        # define the image generator
        self.sdxl_path = kagglehub.model_download('stabilityai/stable-diffusion-xl/PyTorch/base-1-0/1')
        self.doctor_diffusion_vector_path = kagglehub.model_download('architkohli/doctor-diffusion-vector-sdxl/PyTorch/doctor-diffusion/1')
        self.image_generator_pipe = DiffusionPipeline.from_pretrained(self.sdxl_path, torch_dtype=torch.float16, use_safetensors=True, variant="fp16")
        self.image_generator_pipe.to("cuda:0")
        self.image_generator_pipe.load_lora_weights(self.doctor_diffusion_vector_path,weight_name='DD-vector-v2.safetensors')
        
         # define the text generator
        self.model_name = kagglehub.model_download('qwen-lm/qwen2.5/Transformers/7b-instruct/1')
        self.model = AutoModelForCausalLM.from_pretrained(
            self.model_name,
            torch_dtype="auto",
            device_map="cuda:1"
        )
        self.tokenizer = AutoTokenizer.from_pretrained(self.model_name)
        
        self.default_svg = """<svg width="256" height="256" viewBox="0 0 256 256"><circle cx="50" cy="50" r="40" fill="red" /></svg>"""
        self.element_checker = svg_constraints.SVGConstraints()
        self.timeout_seconds = 90

    def rich_prompt(self, description):
        """Enrich the prompt words of the original description"""
        description = f"""
Now I am going to use the Flux model to generate an image based on the following prompt. Please help me refine the prompt:
{description}
The refined prompts should be:
More specific, but simple details.
Visually more beautiful and clean.
Most importantly, with clear lines and a highlighted main subject.
The output should only be the improved and refined prompt based on the original, without any other text.
"""
        messages = [
            {"role": "user", "content": description}
        ]
        text = self.tokenizer.apply_chat_template(
            messages,
            tokenize=False,
            add_generation_prompt=True
        )
        model_inputs = self.tokenizer([text], return_tensors="pt").to(self.model.device)
        generated_ids = self.model.generate(
            **model_inputs,
            max_new_tokens=512
        )
        generated_ids = [
            output_ids[len(input_ids):] for input_ids, output_ids in zip(model_inputs.input_ids, generated_ids)
        ]
        response = self.tokenizer.batch_decode(generated_ids, skip_special_tokens=True)[0]
        return response
        
    def predict(self, description: str, max_new_tokens=512) -> str:
        def generate_svg():
            logging.info(f"original prompt: {description}")
            try:
                with torch.no_grad():
                    prompt = self.rich_prompt(description)
                
                logging.info(f"rich prompt: {prompt}")
                image = self.image_generator_pipe(
                    prompt = prompt,
                    num_inference_steps = 20
                ).images[0]
                svg = bitmap_to_svg_layered(image)
                logging.debug('Unprocessed SVG: %s', svg)
                
                try:
                    self.element_checker.validate_svg(svg)
                except Exception as e:
                    logging.error("Elements that are not allowed appear", svg)
                    return self.default_svg
                    
                logging.debug('Processed SVG: %s', svg)
                # Ensure the generated code can be converted by cairosvg
                cairosvg.svg2png(bytestring=svg.encode('utf-8'))
                return svg
                
            except Exception as e:
                logging.error('Exception during SVG generation: %s', e)
                return self.default_svg

        # Execute SVG generation in a new thread to enforce time constraints
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as executor:
            future = executor.submit(generate_svg)
            try:
                return future.result(timeout=self.timeout_seconds)
            except concurrent.futures.TimeoutError:
                logging.warning("Prediction timed out after %s seconds.", self.timeout_seconds)
                return self.default_svg
            except Exception as e:
                logging.error(f"An unexpected error occurred: {e}")
                return self.default_svg
        return generate_svg(description)



