def create_svg_table_html(data: dict, width: int = 200, height: int = 200) -> str:
  """
  生成一个HTML表格来显示键-SVG对，并控制SVG的大小。

  Args:
    data: 一个字典，其中键是字符串，值是SVG代码字符串。
    width: SVG显示区域的期望宽度（像素）。
    height: SVG显示区域的期望高度（像素）。

  Returns:
    表示表格的HTML字符串。
  """
  html_rows = []
  html_rows.append("<thead><tr><th>键 (Key)</th><th>SVG 图像</th></tr></thead>")
  table_body = "<tbody>\n"
  for key, svg_code in data.items():
    escaped_key = html.escape(str(key))
    # 将SVG包裹在一个具有指定宽度和高度的div中
    # 添加 overflow: hidden 来防止SVG溢出容器
    svg_cell_content = f"<div style='width: {width}px; height: {height}px; overflow: hidden; display: flex; justify-content: center; align-items: center;'>{svg_code}</div>"
    table_body += f"  <tr>\n    <td style='vertical-align: middle;'>{escaped_key}</td>\n    <td>{svg_cell_content}</td>\n  </tr>\n"
  table_body += "</tbody>"
  html_rows.append(table_body)
  html_table = f"<table border='1' style='border-collapse: collapse;'>\n" + "\n".join(html_rows) + "\n</table>"
  return html_table


